/* Local files stay on this device. Audio blobs are committed to IndexedDB. */
const OfflineLibrary=(()=>{
  let database,importing=false,ready=false,dbError='',offlineReady=false;
  const records=new Map(),urls=new Map();
  const bytes=n=>n<1048576?`${(n/1024).toFixed(0)} KB`:`${(n/1048576).toFixed(1)} MB`;
  function open(){if(database)return database;database=new Promise((resolve,reject)=>{const req=indexedDB.open('sonora-offline',1);req.onupgradeneeded=()=>{const store=req.result.createObjectStore('tracks',{keyPath:'id'});store.createIndex('signature','signature',{unique:true})};req.onsuccess=()=>{req.result.onversionchange=()=>req.result.close();resolve(req.result)};req.onerror=()=>reject(req.error);req.onblocked=()=>reject(new Error('Tutup tab Sonora lain, lalu muat ulang.'))});return database}
  async function transaction(mode,work){const db=await open();return new Promise((resolve,reject)=>{const tx=db.transaction('tracks',mode);let value;try{const req=work(tx.objectStore('tracks'));if(req)req.onsuccess=()=>value=req.result}catch(e){tx.abort();reject(e);return}tx.oncomplete=()=>resolve(value);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Penyimpanan dibatalkan'))})}
  function song(record){const url=URL.createObjectURL(record.blob);urls.set(record.id,url);return{id:record.id,title:record.title,artist:'Koleksi offline',album:'Tersimpan di perangkat',kind:'local',genre:'local',duration:record.duration,art:record.art,src:url,size:record.size}}
  function inspect(file){return new Promise((resolve,reject)=>{const player=new Audio(),url=URL.createObjectURL(file);let timer;function done(error){clearTimeout(timer);player.onloadedmetadata=null;player.onerror=null;const duration=player.duration;player.removeAttribute('src');player.load();URL.revokeObjectURL(url);error?reject(error):resolve(duration)}player.onloadedmetadata=()=>done(Number.isFinite(player.duration)&&player.duration>0?null:new Error('Durasi tidak terbaca'));player.onerror=()=>done(new Error('Format audio tidak bisa diputar'));timer=setTimeout(()=>done(new Error('File tidak dapat dibaca')),8000);player.preload='metadata';player.src=url})}
  function renderUI(){const panel=document.querySelector('#offlineLibrary');if(!panel)return;panel.hidden=!(view==='home'&&mode==='local');const total=[...records.values()].reduce((sum,r)=>sum+r.size,0);document.querySelector('#offlineCount').textContent=`${records.size} lagu · ${bytes(total)}`;document.querySelector('#offlineState').textContent=dbError?'Penyimpanan tidak tersedia':!ready?'Membaca koleksi…':offlineReady?'Aplikasi siap dibuka offline':'Lagu tersimpan · menyiapkan akses offline';document.querySelector('#offlineStatus').textContent=!navigator.onLine?'● Offline':offlineReady?'✓ Siap offline':'○ Online';document.querySelector('#offlineStatus').classList.toggle('is-offline',!navigator.onLine);document.querySelector('#importFiles').disabled=importing||!ready||!!dbError;document.querySelector('#importFiles').textContent=importing?'Menyimpan…':'＋ Tambahkan lagu';document.querySelector('#importProgress').hidden=!importing;document.querySelector('#offlineError').textContent=dbError;document.querySelector('#offlineError').hidden=!dbError;}
  async function importFiles(files){if(importing)return;if(!ready||dbError){toast('Penyimpanan belum siap. Muat ulang dan coba lagi.');return}importing=true;renderUI();let added=0,duplicate=0,failed=0;const known=new Set([...records.values()].map(r=>r.signature)),list=Array.from(files),progress=document.querySelector('#importProgress');try{for(let i=0;i<list.length;i++){const file=list[i];progress.textContent=`Menyimpan ${i+1} dari ${list.length}: ${file.name}`;const signature=JSON.stringify([file.name,file.size,file.lastModified]);if(known.has(signature)){duplicate++;continue}if(!(file.type.startsWith('audio/')||/\.(mp3|wav|ogg|m4a|flac|aac|opus)$/i.test(file.name))){failed++;continue}try{const duration=await inspect(file),record={id:'local-'+crypto.randomUUID(),signature,title:file.name.replace(/\.[^.]+$/,''),filename:file.name,size:file.size,duration,art:records.size%6,blob:file,createdAt:Date.now()};await transaction('readwrite',store=>store.add(record));records.set(record.id,record);known.add(signature);songs.push(song(record));added++;}catch(error){failed++;if(error?.name==='QuotaExceededError'){toast('Penyimpanan penuh. Hapus beberapa lagu lalu coba lagi.');break}}}if(added){navigator.storage?.persist?.().catch(()=>{});setMode('local')}const summary=[added?`${added} lagu tersimpan untuk offline`:null,duplicate?`${duplicate} duplikat dilewati`:null,failed?`${failed} file gagal disimpan atau tidak didukung`:null].filter(Boolean).join(' · ');toast(summary||'Tidak ada file yang ditambahkan');}finally{importing=false;document.querySelector('#files').value='';render();renderUI()}}
  async function remove(id){const record=records.get(id);if(!record)return;try{await transaction('readwrite',store=>store.delete(id));if(currentId===id){playId++;audio.pause();audio.removeAttribute('src');audio.load();currentId='';document.querySelector('#nowTitle').textContent='Pilih musik favoritmu';document.querySelector('#nowArtist').textContent='Koleksi offline';document.querySelector('#nowCover').innerHTML='';document.querySelector('#playbackStatus').textContent='';document.querySelector('#elapsed').textContent='0:00';document.querySelector('#duration').textContent='0:00';document.querySelector('#seek').value=0;document.querySelector('#nowSource').hidden=true;document.querySelector('#toggle').innerHTML=icon('play');document.querySelector('#toggle').ariaLabel='Putar'}URL.revokeObjectURL(urls.get(id));urls.delete(id);records.delete(id);songs=songs.filter(s=>s.id!==id);likes.delete(id);for(const p of playlists)p.songs=p.songs.filter(x=>x!==id);save();render();toast('Salinan offline dihapus. File asli tetap ada.')}catch{toast('Lagu belum berhasil dihapus. Coba lagi.')}}
  async function setupOffline(){if(!('serviceWorker' in navigator)){document.querySelector('#offlineHint').textContent='Browser ini belum mendukung membuka aplikasi offline. Lagu lokal tetap tersimpan.';return}try{await navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'});await Promise.race([navigator.serviceWorker.ready,new Promise((_,reject)=>setTimeout(()=>reject(new Error("Offline setup timeout")),15000))]);const cache=await caches.open('sonora-shell-v1');offlineReady=!!(await cache.match(new URL('./',location.href).href));if(!offlineReady)throw new Error('Shell not cached');}catch{document.querySelector('#offlineHint').textContent='Lagu lokal tersimpan. Untuk menyiapkan aplikasi offline, buka lagi saat terhubung internet.'}renderUI()}
  async function init(){document.querySelector('#importFiles').onclick=()=>document.querySelector('#files').click();document.addEventListener('click',e=>{const removeButton=e.target.closest('[data-remove-local]');if(removeButton)remove(removeButton.dataset.removeLocal)});const zone=document.querySelector('#dropZone');let depth=0;zone.addEventListener('dragenter',e=>{e.preventDefault();depth++;zone.classList.add('dragging')});zone.addEventListener('dragover',e=>e.preventDefault());zone.addEventListener('dragleave',()=>{if(--depth<=0){depth=0;zone.classList.remove('dragging')}});zone.addEventListener('drop',e=>{e.preventDefault();depth=0;zone.classList.remove('dragging');importFiles(e.dataTransfer.files)});window.addEventListener('online',()=>{renderUI();if(view==='home'&&['music','radio'].includes(mode))loadCatalog()});window.addEventListener('offline',()=>{if(view==='home'&&['music','radio'].includes(mode))setMode('local');renderUI()});try{const saved=await transaction('readonly',store=>store.getAll());for(const record of saved){records.set(record.id,record);songs.push(song(record))}ready=true;}catch{dbError='Koleksi tidak dapat dibuka. Izinkan penyimpanan situs di browser, lalu muat ulang.'}if(!navigator.onLine||localStorage.getItem('sonora-last-mode')==='local')setMode('local');render();renderUI();setupOffline()}
  return{init,importFiles,renderUI,remove};
})();
